"use client";

import * as React from "react";
import { ChevronDown, Minus, Plus } from "lucide-react";
import { NumberRoll } from "./number-roll";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

export interface FloatingToolItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  shortcut?: string;
  active?: boolean;
  onClick?: () => void;
  disabled?: boolean;
}

export interface FloatingMenuItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  destructive?: boolean;
  onSelect: () => void;
}

export interface FloatingButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  tools: FloatingToolItem[];
  activeId?: string;
  onToolSelect?: (id: string) => void;
  /** Stepper zoom or counter value (e.g. 100) */
  zoomValue?: number;
  onZoomChange?: (newZoom: number) => void;
  /** Optional secondary menu items opened by trailing chevron */
  menuItems?: FloatingMenuItem[];
  /** Positioning mode */
  dock?: "inline" | "bottom" | "top";
  label?: string;
}

const EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const UI = "cubic-bezier(0.23, 1, 0.32, 1)";
const OPEN = 280;
const CLOSE = 200;
const ROW_H = 32;

type Phase = "closed" | "opening" | "open" | "closing";
type Box = { left: number; top: number; width: number; height: number };

export function FloatingButtonGroup({
  tools,
  activeId: controlledActiveId,
  onToolSelect,
  zoomValue,
  onZoomChange,
  menuItems,
  dock = "inline",
  label = "Floating toolbar",
  className = "",
  style,
  ...props
}: FloatingButtonGroupProps) {
  const reduced = useInteractionReducedMotion();
  const [internalActiveId, setInternalActiveId] = React.useState<string>(
    tools[0]?.id ?? "",
  );

  // FilterBar-style morphing dropdown state
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [box, setBox] = React.useState<Box>({
    left: 0,
    top: 0,
    width: 0,
    height: 36,
  });
  const [panelH, setPanelH] = React.useState(0);
  const [menuActiveIndex, setMenuActiveIndex] = React.useState(0);

  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const timer = React.useRef<number>(0);

  const activeTool =
    controlledActiveId !== undefined ? controlledActiveId : internalActiveId;

  // One indicator for the active tool. Measured from layout offsets (transforms ignored, so a
  // pressed button's scale never skews it) and placed once without a transition.
  const [mark, setMark] = React.useState<{
    x: number;
    y: number;
    w: number;
    h: number;
  } | null>(null);
  const [markReady, setMarkReady] = React.useState(false);
  React.useLayoutEffect(() => {
    const wrap = containerRef.current;
    if (!wrap) return;
    const measure = () => {
      const el = wrap.querySelector<HTMLElement>(
        `[data-tool-id="${CSS.escape(activeTool)}"]`,
      );
      if (!el) return setMark(null);
      const next = {
        x: el.offsetLeft,
        y: el.offsetTop,
        w: el.offsetWidth,
        h: el.offsetHeight,
      };
      setMark((p) =>
        p &&
        p.x === next.x &&
        p.y === next.y &&
        p.w === next.w &&
        p.h === next.h
          ? p
          : next,
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(wrap);
    return () => ro.disconnect();
  }, [activeTool, tools]);
  React.useEffect(() => {
    if (!mark || markReady) return;
    const frame = requestAnimationFrame(() => setMarkReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, markReady]);

  // Clean dropdown timer
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  // FilterBar double-rAF expansion
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setPhase("open"));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  // Measure dropdown panel height
  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelH(panel.offsetHeight);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(panel);
    return () => ro.disconnect();
  }, [menuItems, phase]);

  const openDropdown = () => {
    const wrap = containerRef.current;
    const trigger = triggerRef.current;
    if (!wrap || !trigger) return;
    window.clearTimeout(timer.current);
    const a = trigger.getBoundingClientRect();
    const w = wrap.getBoundingClientRect();
    setBox({
      left: a.left - w.left,
      top: a.top - w.top,
      width: a.width,
      height: a.height,
    });
    setMenuActiveIndex(0);
    setPhase(reduced ? "open" : "opening");
  };

  const closeDropdown = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) {
        setPhase("closed");
        return;
      }
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), CLOSE);
    },
    [reduced],
  );

  // Close dropdown on outside pointer
  React.useEffect(() => {
    if (phase === "closed" || phase === "closing") return;
    const onDown = (e: PointerEvent) => {
      if (!containerRef.current?.contains(e.target as Node)) {
        closeDropdown(false);
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeDropdown(true);
    };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [phase, closeDropdown]);

  // Handle keyboard arrows across tools or inside menu
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (phase === "open") {
      if (!menuItems?.length) return;
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setMenuActiveIndex((i) => (i < menuItems.length - 1 ? i + 1 : 0));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setMenuActiveIndex((i) => (i > 0 ? i - 1 : menuItems.length - 1));
      } else if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        const item = menuItems[menuActiveIndex];
        if (item) {
          closeDropdown(true);
          item.onSelect();
        }
      }
      return;
    }

    const enabled = tools.filter((tool) => !tool.disabled);
    const focusedId = (document.activeElement as HTMLElement | null)?.dataset
      .toolId;
    const currentIndex = enabled.findIndex((tool) => tool.id === focusedId);
    if (currentIndex < 0) return;

    let next = -1;
    if (e.key === "ArrowRight") next = (currentIndex + 1) % enabled.length;
    else if (e.key === "ArrowLeft")
      next = (currentIndex - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;

    const nextTool = enabled[next];
    if (nextTool) {
      e.preventDefault();
      containerRef.current
        ?.querySelector<HTMLElement>(
          `[data-tool-id="${CSS.escape(nextTool.id)}"]`,
        )
        ?.focus();
      handleToolClick(nextTool);
    }
  };

  const handleToolClick = (tool: FloatingToolItem) => {
    if (tool.disabled) return;
    if (controlledActiveId === undefined) setInternalActiveId(tool.id);
    onToolSelect?.(tool.id);
    tool.onClick?.();
  };

  const dockClass =
    dock === "bottom"
      ? "fixed bottom-6 left-1/2 -translate-x-1/2 z-40"
      : dock === "top"
        ? "fixed top-6 left-1/2 -translate-x-1/2 z-40"
        : "relative inline-flex";

  const mounted = phase !== "closed";
  const expanded = phase === "open";
  const MENU_W = 180;
  const targetLeft = Math.max(0, box.left + box.width - MENU_W);
  // A toolbar docked to the bottom opens its menu upward.
  const targetTop =
    dock === "bottom"
      ? box.top - 6 - (expanded ? panelH : box.height)
      : box.top + box.height + 6;

  return (
    <div
      ref={containerRef}
      role="toolbar"
      aria-label={label}
      onKeyDown={handleKeyDown}
      style={style}
      className={`${dockClass} items-center rounded-full p-1 gap-1 select-none isolate bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] max-w-[calc(100vw-32px)] overflow-visible ${className}`}
      {...props}
    >
      {/* The active tool's indicator, thrown to the next tool with a slight overshoot. */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute left-0 top-0 z-0 rounded-full bg-accent"
        style={{
          transform: `translate3d(${mark?.x ?? 0}px, ${mark?.y ?? 0}px, 0)`,
          width: mark?.w ?? 0,
          height: mark?.h ?? 0,
          opacity: mark ? 1 : 0,
          transition:
            reduced || !markReady
              ? "none"
              : `transform 420ms ${EASE_THROW}, width 380ms ${EASE_OUT}, height 380ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
        }}
      />

      {/* Main Tools Row */}
      {tools.map((tool) => {
        const isActive = activeTool === tool.id;

        return (
          <button
            key={tool.id}
            type="button"
            data-tool-id={tool.id}
            disabled={tool.disabled}
            aria-label={
              tool.shortcut ? `${tool.label} (${tool.shortcut})` : tool.label
            }
            aria-pressed={isActive}
            onClick={() => handleToolClick(tool)}
            tabIndex={
              isActive ||
              (!tools.some((t) => t.id === activeTool) && tool === tools[0])
                ? 0
                : -1
            }
            className={`relative z-10 flex size-8 items-center justify-center rounded-full cursor-pointer disabled:cursor-default disabled:opacity-40 ${INTERACTION_PRESS} ${
              isActive
                ? "text-foreground"
                : "text-muted-foreground hover:bg-accent/60 hover:text-foreground"
            } ${INTERACTION_FOCUS}`}
          >
            <span className="size-4 shrink-0 inline-flex items-center justify-center">
              {tool.icon}
            </span>
          </button>
        );
      })}

      {/* Optional Stepper / Zoom controls */}
      {zoomValue !== undefined && onZoomChange && (
        <>
          <span
            aria-hidden="true"
            className="w-px h-4 bg-border shrink-0 mx-0.5"
          />
          <div className="flex items-center gap-0.5 text-[12px] font-medium tabular-nums text-muted-foreground">
            <button
              type="button"
              aria-label="Zoom out"
              disabled={zoomValue <= 25}
              onClick={() => onZoomChange(Math.max(25, zoomValue - 10))}
              className={`flex size-8 items-center justify-center rounded-full cursor-pointer hover:bg-accent/60 hover:text-foreground disabled:cursor-default disabled:opacity-40 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
            >
              <Minus size={14} strokeWidth={1.75} />
            </button>
            <span className="min-w-[42px] text-center text-foreground">
              <NumberRoll value={zoomValue} suffix="%" />
            </span>
            <button
              type="button"
              aria-label="Zoom in"
              disabled={zoomValue >= 300}
              onClick={() => onZoomChange(Math.min(300, zoomValue + 10))}
              className={`flex size-8 items-center justify-center rounded-full cursor-pointer hover:bg-accent/60 hover:text-foreground disabled:cursor-default disabled:opacity-40 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
            >
              <Plus size={14} strokeWidth={1.75} />
            </button>
          </div>
        </>
      )}

      {/* Optional Dropdown Menu Trigger */}
      {menuItems && menuItems.length > 0 && (
        <>
          <span
            aria-hidden="true"
            className="w-px h-4 bg-border shrink-0 mx-0.5"
          />
          <button
            ref={triggerRef}
            type="button"
            aria-haspopup="menu"
            aria-expanded={mounted && phase !== "closing"}
            aria-label="Toolbar options"
            onClick={(e) => {
              e.stopPropagation();
              if (mounted && phase !== "closing") closeDropdown();
              else openDropdown();
            }}
            className={`relative z-10 flex size-8 items-center justify-center rounded-full cursor-pointer text-muted-foreground hover:bg-accent/60 hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
          >
            <ChevronDown
              size={13}
              strokeWidth={1.75}
              style={{
                transform:
                  mounted && phase !== "closing" ? "rotate(180deg)" : "none",
                transition: reduced ? "none" : `transform 300ms ${EASE}`,
              }}
            />
          </button>
        </>
      )}

      {/* FilterBar Morphing Dropdown Panel */}
      {mounted && menuItems && menuItems.length > 0 && (
        <div
          role="menu"
          className="absolute z-50 overflow-hidden bg-popover text-popover-foreground"
          style={{
            top: targetTop,
            left: expanded ? targetLeft : box.left,
            width: expanded ? MENU_W : box.width,
            height: expanded ? panelH : box.height,
            borderRadius: expanded ? 12 : box.height / 2,
            opacity: expanded ? 1 : 0,
            boxShadow: "0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : phase === "closing"
                ? `width ${CLOSE}ms ${UI}, height ${CLOSE}ms ${UI}, left ${CLOSE}ms ${UI}, top ${CLOSE}ms ${UI}, border-radius ${CLOSE}ms ${UI}, opacity ${CLOSE}ms ${UI}`
                : `width ${OPEN}ms ${UI}, height ${OPEN}ms ${UI}, left ${OPEN}ms ${UI}, top ${OPEN}ms ${UI}, border-radius ${OPEN}ms ${UI}, opacity 160ms ${UI}`,
          }}
        >
          <div
            ref={panelRef}
            inert={!expanded ? true : undefined}
            className="relative p-1"
            style={{
              width: MENU_W,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : expanded
                  ? `opacity 180ms ${EASE} 60ms`
                  : "opacity 90ms ease-out",
            }}
          >
            {/* Gliding Row Highlight inside Menu */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-1 top-1 h-8 rounded-[7px] bg-accent"
              style={{
                transform: `translateY(${menuActiveIndex * ROW_H}px)`,
                opacity: menuActiveIndex >= 0 ? 1 : 0,
                transition: reduced ? "none" : `transform 160ms ${UI}`,
              }}
            />

            {menuItems.map((item, index) => (
              <button
                key={item.id}
                type="button"
                role="menuitem"
                onPointerEnter={() => setMenuActiveIndex(index)}
                onClick={() => {
                  closeDropdown(false);
                  item.onSelect();
                }}
                className={`relative z-10 flex h-8 w-full items-center gap-2 rounded-[7px] px-2.5 text-[13px] font-medium transition-colors cursor-pointer select-none text-left ${
                  item.destructive
                    ? menuActiveIndex === index
                      ? "text-red-600 dark:text-red-400 font-semibold"
                      : "text-red-500/90"
                    : menuActiveIndex === index
                      ? "text-foreground font-semibold"
                      : "text-muted-foreground"
                } ${INTERACTION_FOCUS}`}
              >
                {item.icon && (
                  <span className="inline-flex size-3.5 shrink-0 items-center justify-center text-muted-foreground">
                    {item.icon}
                  </span>
                )}
                <span className="truncate flex-1">{item.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default FloatingButtonGroup;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

